"use strict";(globalThis.webpackChunk_viben_docs=globalThis.webpackChunk_viben_docs||[]).push([[3853],{79066(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/viben/blog/welcome","editUrl":"https://github.com/LinXueyuanStdio/viben/edit/main/apps/docs/blog/2025-02-01-welcome.md","source":"@site/blog/2025-02-01-welcome.md","title":"Viben: Agent Swarm \xd7 Code Evolution","description":"\u6b22\u8fce\u6765\u5230 Viben \u2014\u2014 \u4e0b\u4e00\u4ee3 Agent Swarm \u4e0e\u4ee3\u7801\u8fdb\u5316\u5e73\u53f0\uff01","date":"2025-02-01T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/viben/blog/tags/announcement"},{"inline":true,"label":"agent-swarm","permalink":"/viben/blog/tags/agent-swarm"},{"inline":true,"label":"code-evolution","permalink":"/viben/blog/tags/code-evolution"},{"inline":true,"label":"filerl","permalink":"/viben/blog/tags/filerl"},{"inline":true,"label":"mcp","permalink":"/viben/blog/tags/mcp"}],"readingTime":1.44,"hasTruncateMarker":true,"authors":[{"name":"Viben Team","title":"Maintainers","url":"https://github.com/LinXueyuanStdio/viben","imageURL":"https://github.com/LinXueyuanStdio.png","key":"viben-team","page":null}],"frontMatter":{"slug":"welcome","title":"Viben: Agent Swarm \xd7 Code Evolution","authors":["viben-team"],"tags":["announcement","agent-swarm","code-evolution","filerl","mcp"]},"unlisted":false},"content":"\u6b22\u8fce\u6765\u5230 **Viben** \u2014\u2014 \u4e0b\u4e00\u4ee3 Agent Swarm \u4e0e\u4ee3\u7801\u8fdb\u5316\u5e73\u53f0\uff01\\n\\nViben \u901a\u8fc7\u591a\u667a\u80fd\u4f53\u534f\u4f5c\u548c\u5f3a\u5316\u5b66\u4e60\u9a71\u52a8\u7684\u4ee3\u7801\u8fed\u4ee3\uff0c\u91cd\u65b0\u5b9a\u4e49\u8f6f\u4ef6\u5f00\u53d1\u4f53\u9a8c\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u4ec0\u4e48\u662f Viben\uff1f\\n\\nViben \u662f\u4e00\u4e2a\u878d\u5408 **Agent Swarm\uff08\u667a\u80fd\u4f53\u96c6\u7fa4\uff09** \u4e0e **Code Evolution\uff08\u4ee3\u7801\u8fdb\u5316\uff09** \u7406\u5ff5\u7684\u5f00\u53d1\u5e73\u53f0\u3002\u5b83\u4e0d\u4ec5\u4ec5\u662f\u5de5\u5177\uff0c\u800c\u662f\u4e00\u5957\u5b8c\u6574\u7684\u667a\u80fd\u5f00\u53d1\u751f\u6001\u7cfb\u7edf\u3002\\n\\n### \u6838\u5fc3\u7279\u6027\\n\\n#### \ud83e\uddec FileRL - \u4ee3\u7801\u8fed\u4ee3\u4f18\u5316\\n\\n\u57fa\u4e8e\u5f3a\u5316\u5b66\u4e60\u7684\u4ee3\u7801\u8fdb\u5316\u5f15\u64ce\uff0c\u901a\u8fc7\u6301\u7eed\u8fed\u4ee3\u8ba9\u4ee3\u7801\u81ea\u6211\u4f18\u5316\uff1a\\n\\n- \u81ea\u52a8\u5316\u4ee3\u7801\u8d28\u91cf\u8bc4\u4f30\\n- \u667a\u80fd\u91cd\u6784\u5efa\u8bae\\n- \u6e10\u8fdb\u5f0f\u6027\u80fd\u4f18\u5316\\n\\n#### \ud83e\udd16 Multi-Agent - \u667a\u80fd\u4f53\u96c6\u7fa4\u7f16\u6392\\n\\n\u591a\u4e2a\u4e13\u4e1a\u667a\u80fd\u4f53\u534f\u540c\u5de5\u4f5c\uff0c\u5404\u53f8\u5176\u804c\uff1a\\n\\n- \u4ee3\u7801\u751f\u6210\u667a\u80fd\u4f53\\n- \u4ee3\u7801\u5ba1\u67e5\u667a\u80fd\u4f53\\n- \u6d4b\u8bd5\u751f\u6210\u667a\u80fd\u4f53\\n- \u6587\u6863\u751f\u6210\u667a\u80fd\u4f53\\n\\n#### \ud83d\udccb Task System - XState \u72b6\u6001\u673a\u9a71\u52a8\\n\\n\u57fa\u4e8e XState \u7684\u4efb\u52a1\u7ba1\u7406\u7cfb\u7edf\uff0c\u8ba9\u5f00\u53d1\u6d41\u7a0b\u53ef\u89c6\u5316\u3001\u53ef\u8ffd\u8e2a\uff1a\\n\\n- \u4efb\u52a1\u72b6\u6001\u6d41\u8f6c\uff1a`backlog \u2192 queue \u2192 in_progress \u2192 review \u2192 completed`\\n- \u5e76\u53d1\u63a7\u5236\u4e0e\u540e\u53f0\u6267\u884c\\n- Gateway \u91cd\u542f\u81ea\u52a8\u6062\u590d\\n\\n#### \ud83d\udca1 Idea Generation - \u521b\u610f\u5b75\u5316\\n\\n\u4ece\u7075\u611f\u5230\u5b9e\u73b0\u7684\u5b8c\u6574\u94fe\u8def\uff1a\\n\\n- \u9700\u6c42\u5206\u6790\u4e0e\u62c6\u89e3\\n- \u6280\u672f\u65b9\u6848\u751f\u6210\\n- \u539f\u578b\u5feb\u901f\u9a8c\u8bc1\\n\\n#### \ud83d\udd0c MCP Protocol - \u751f\u6001\u96c6\u6210\\n\\n\u517c\u5bb9 MCP (Model Context Protocol) \u6807\u51c6\uff0c\u65e0\u7f1d\u5bf9\u63a5\u73b0\u6709 AI \u751f\u6001\uff1a\\n\\n- \u4e0e Claude \u7b49 MCP \u5ba2\u6237\u7aef\u6df1\u5ea6\u96c6\u6210\\n- \u53ef\u6269\u5c55\u7684\u5de5\u5177\u96c6\\n- \u5f00\u653e\u7684\u534f\u8bae\u6807\u51c6\\n\\n## \u5f00\u59cb\u4f7f\u7528\\n\\n```bash\\n# \u5b89\u88c5 Viben CLI\\npnpm install -g viben\\n\\n# \u521d\u59cb\u5316\u9879\u76ee\\nviben init\\n\\n# \u542f\u52a8 Gateway\\nviben gateway start\\n```\\n\\n\u67e5\u770b\u6211\u4eec\u7684[\u6587\u6863](/user/intro)\u4e86\u89e3\u66f4\u591a\uff01\\n\\n## \u613f\u666f\\n\\n\u6211\u4eec\u76f8\u4fe1\uff0c\u672a\u6765\u7684\u8f6f\u4ef6\u5f00\u53d1\u5c06\u7531\u667a\u80fd\u4f53\u96c6\u7fa4\u9a71\u52a8\uff0c\u4ee3\u7801\u5c06\u50cf\u751f\u547d\u4e00\u6837\u4e0d\u65ad\u8fdb\u5316\u3002Viben \u6b63\u662f\u4e3a\u8fd9\u4e2a\u672a\u6765\u800c\u751f\u3002\\n\\n**Agent Swarm \xd7 Code Evolution** \u2014\u2014 \u8ba9\u4ee3\u7801\u81ea\u5df1\u8fdb\u5316\u3002"}]}}')}}]);